perl -e '
use strict;
use warnings;

# Load all go files
open my $af, "<", "/tmp/all_go_files.txt" or die $!;
my @all = map { chomp; $_ } <$af>;

# Also include test files under internal that might have been included
# all_go_files already has all .go

# Parse declarations from internal non-test files
open my $lf, "<", "/tmp/internal_go_files.txt" or die $!;
my @ifiles = map { chomp; $_ } <$lf>;

my @decls;
my %by_name;
for my $f (@ifiles) {
  my $pkg = "";
  my $rel = $f; $rel =~ s{^/bench/repo/}{};
  open my $fh, "<", $f or die $!;
  my $lineno = 0;
  while (my $line = <$fh>) {
    $lineno++;
    if ($line =~ /^package\s+(\w+)/) { $pkg = $1; }
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1 // "", $2);
      $recv =~ s/\s+/ /g;
      next if $name eq "init";
      my $d = { file => $rel, full => $f, line => $lineno, recv => $recv, name => $name, pkg => $pkg, is_method => ($recv ne "") };
      push @decls, $d;
      push @{$by_name{$name}}, $d;
    }
  }
}

# Read all source files into memory (stripped of comments roughly)
my %file_pkg;
my %file_lines; # file -> [lines]
for my $f (@all) {
  open my $fh, "<", $f or die "$f: $!";
  my @lines;
  my $pkg = "";
  my $in_block = 0;
  while (my $line = <$fh>) {
    # strip block comments crudely
    if ($in_block) {
      if ($line =~ s/.*?\*\///) { $in_block = 0; }
      else { $line = "\n"; }
    }
    while ($line =~ s/\/\*.*?\*\///g) {}
    if ($line =~ s/\/\*.*//) { $in_block = 1; }
    $line =~ s/\/\/.*//;
    if ($line =~ /^\s*package\s+(\w+)/) { $pkg = $1; }
    push @lines, $line;
  }
  $file_pkg{$f} = $pkg;
  $file_lines{$f} = \@lines;
}

# Count call sites for each unique name that has a single declaration
# For names with multiple decls, skip or handle separately
my @results;
for my $d (@decls) {
  my $name = $d->{name};
  my $n_overloads = scalar @{$by_name{$name}};
  # Skip highly overloaded / interface marker methods
  next if $name =~ /^(isCondition|isValueExpr|isPredicateExpr|matches)$/;

  my $call_sites = 0;
  my $call_sites_notest = 0;
  my %caller_files;
  my %caller_files_notest;
  my %caller_funcs;
  my $current_func = "";

  my $is_method = $d->{is_method};
  my $pkg = $d->{pkg};

  for my $f (@all) {
    my $fpkg = $file_pkg{$f} // "";
    my $is_test = ($f =~ /_test\.go$/);
    my $rel = $f; $rel =~ s{^/bench/repo/}{};
    my $lineno = 0;
    for my $line (@{$file_lines{$f}}) {
      $lineno++;
      if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
        $current_func = ($1 ? "($1) " : "") . $2;
      }

      # skip the declaration itself
      if ($rel eq $d->{file} && $lineno == $d->{line}) { next; }

      my $matched = 0;
      if ($is_method) {
        # method call: .Name(  but not func (x) Name(
        if ($line =~ /\.$name\s*\(/) { $matched = 1; }
      } else {
        if ($fpkg eq $pkg) {
          # same package: Name( not preceded by . or ident.
          if ($line =~ /(?:^|[^.\w])$name\s*\(/) { $matched = 1; }
        } else {
          # cross package: pkg.Name(
          if ($line =~ /\b\Q$pkg\E\.$name\s*\(/) { $matched = 1; }
        }
      }
      if ($matched) {
        $call_sites++;
        $caller_files{$rel}++;
        $caller_funcs{"$rel:$current_func"}++;
        unless ($is_test) {
          $call_sites_notest++;
          $caller_files_notest{$rel}++;
        }
      }
    }
  }

  push @results, {
    name => $name,
    file => $d->{file},
    recv => $d->{recv},
    pkg => $pkg,
    overloads => $n_overloads,
    sites => $call_sites,
    sites_nt => $call_sites_notest,
    files => scalar keys %caller_files,
    files_nt => scalar keys %caller_files_notest,
    funcs => scalar keys %caller_funcs,
  };
}

@results = sort { $b->{sites} <=> $a->{sites} || $b->{funcs} <=> $a->{funcs} } @results;
print "TOP 40 by call sites (all files including tests)\n";
printf "%-40s %-50s %6s %6s %6s %6s %6s %s\n", "SYMBOL", "FILE", "SITES", "S_NT", "FILES", "F_NT", "FUNCS", "OV";
for my $i (0..39) {
