# Exact counts and unique enclosing functions for top candidates
perl -e '
use strict;
use warnings;

sub analyze {
  my ($pattern, $decl_skip) = @_;
  my %funcs;
  my $sites = 0;
  my %files;
  open my $lf, "<", "/tmp/all_go_files.txt" or die $!;
  while (my $f = <$lf>) {
    chomp $f;
    open my $fh, "<", $f or die $!;
    my $cur = "?";
    my $ln = 0;
    my $rel = $f; $rel =~ s{^/bench/repo/}{};
    while (my $line = <$fh>) {
      $ln++;
      if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)/) {
        $cur = ($1 ? "($1) " : "") . $2;
      }
      next if $decl_skip && $rel eq $decl_skip->{file} && $ln == $decl_skip->{line};
      # strip comments
      $line =~ s/\/\/.*//;
      if ($line =~ /$pattern/) {
        $sites++;
        $files{$rel}++;
        $funcs{"$rel :: $cur"}++;
      }
    }
  }
  return ($sites, scalar(keys %files), scalar(keys %funcs), \%funcs, \%files);
}

